from Crypto.Util.number import *
import random
from secret import flag

e = 65537
m = bytes_to_long(flag)

def encrypt(m):
    p = getPrime(512)
    q = getPrime(500)
    n = p * q
    c = pow(m, e, n)
    return c,n,p + (random.getrandbits(230) << 282)

c,h1,h2 = encrypt(m)
hint1 = [h1]
hint2 = [h2]

for _ in range(5):
    c,h1,h2 = encrypt(c)
    hint1.append(h1)
    hint2.append(h2)

print(f"c = {c}")
print(f"hint1 = {hint1}")
print(f"hint2 = {hint2}")

